import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    adj = [[] for _ in range(n + 1)]
    edges = []

    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        edges.append((u, v))

    def has_cycle():
        visited = [0] * (n + 1)
        rec_stack = [0] * (n + 1)

        def dfs(u):
            visited[u] = 1
            rec_stack[u] = 1
            for v in adj[u]:
                if not visited[v]:
                    if dfs(v):
                        return True
                elif rec_stack[v]:
                    return True
            rec_stack[u] = 0
            return False

        for i in range(1, n + 1):
            if not visited[i]:
                if dfs(i):
                    return True
        return False

    if not has_cycle():
        print("YES")
        return

    for idx, (u, v) in enumerate(edges):
        temp_adj = [lst[:] for lst in adj]
        temp_adj[u].remove(v)

        visited = [0] * (n + 1)
        in_stack = [0] * (n + 1)

        stack = []
        possible = True

        for start in range(1, n + 1):
            if visited[start]:
                continue
            stack.append(start)
            while stack:
                node = stack[-1]
                if visited[node] == 1:
                    stack.pop()
                    in_stack[node] = 0
                    continue

                visited[node] = 1
                in_stack[node] = 1

                found_unvisited = False
                for neighbor in temp_adj[node]:
                    if not visited[neighbor]:
                        stack.append(neighbor)
                        found_unvisited = True
                        break
                    elif in_stack[neighbor]:
                        possible = False
                        break

                if not found_unvisited and stack:
                    stack.pop()
                    in_stack[node] = 0

                if not possible:
                    break

            if not possible:
                break

        if possible:
            print("YES")
            return

    print("NO")

if __name__ == "__main__":
    solve()
